@dataclass(kw_only=True)
class AudioStreamFormat(AudioStreamFormatType):
    """
    A combination of tracks (or one track) required to represent a channel
    or a pack.

    The audioStreamFormat establishes a relation between audioTrackFormats
    stored in the asset and audioChannelFormats produced by these
    audioTrackFormats. Its main use is to deal with non-PCM encoded tracks,
    where one or several audioTrackFormats produce several
    audioChannelFormats. The audioStreamFormat allows knowing which
    audioChannelFormats are available on an asset and how to effectively
    access to them. An audio stream can also be used to link together
    several PCM audioTrackFormats.
    """

    class Meta:
        name = "audioStreamFormat"
        namespace = "urn:ebu:metadata-schema:ebucore"


