@dataclass(kw_only=True)
class AudioPackFormat(AudioPackFormatType):
    """
    The audioPackFormat brings together one or more audioChannelFormats
    that belong together.

    For example 'stereo' and '5.1' would be audioPackFormats for
    channel-based formats. It can also contain references to other packs to
    allow nesting. To help define the type of channels described within the
    pack, a typeDefintion is used to define them. The
    typeDefinition/typeLabel must match those in the referred
    audioChannelFormats: DirectSpeakers: For channel-based audio, where
    each channel feeds a speaker directly. Type 0001. Matrix: For
    channel-based audio where channels are matrixed together, such as
    Mid-Side, Lt/Rt. Type 0002. Objects: For object-based audio where
    channels represent audio objects (or parts of objects), so include
    positional information. Type 0003. HOA: For scene-based audio where
    Ambisonics and HOA are used. Type 0004. Binaural:For binaural audio,
    where playback is over headphones. Type 0005.
    """

    class Meta:
        name = "audioPackFormat"
        namespace = "urn:ebu:metadata-schema:ebucore"


