@dataclass(kw_only=True)
class AudioBlockFormat(AudioBlockFormatType):
    """
    An audioBlockFormat represents a single sequence of audio samples with
    fixed parameters, including position, within a specified time.

    The sub-elements with audioBlockFormat are dependent upon the
    typeDefintion or typeLabel of the parent audioChannelFormat element.
    Currently, there are five different typeDefinitions: DirectSpeakers:
    For channel-based audio, where each channel feeds a speaker directly.
    Type 0001. Matrix: For channel-based audio where channels are matrixed
    together, such as Mid-Side, Lt/Rt. Type 0002. Objects: For object-based
    audio where channels represent audio objects (or parts of objects), so
    include positional information. Type 0003. HOA: For scene-based audio
    where Ambisonics and HOA are used. Type 0004. Binaural:For binaural
    audio, where playback is over headphones. Type 0005.
    """

    class Meta:
        name = "audioBlockFormat"
        namespace = "urn:ebu:metadata-schema:ebucore"


