@dataclass(kw_only=True)
class AudioChannelFormat(AudioChannelFormatType):
    """
    An audio channel represents a single sequence of audio samples.

    An audioChannelFormat represents a single sequence of audio samples. It
    is sub-divided in the time domain into audioBlockFormats, which is must
    contain at least one of. The typeDefintion of the audioChannelFormat
    specifies the type of audio it is describing, and also determines which
    parameters are used within its audioBlockFormat children. Currently,
    there are five different typeDefinitions: DirectSpeakers: For
    channel-based audio, where each audio channel feeds a speaker directly.
    Type 0001. Matrix: For channel-based audio where channels are matrixed
    together, such as Mid-Side, Lt/Rt. Type 0002. Objects: For object-based
    audio where channels represent audio objects (or parts of objects), so
    include positional information. Type 0003. HOA: For scene-based audio
    where Ambisonics and HOA are used. Type 0004. Binaural:For binaural
    audio, where playback is over headphones. Type 0005.
    """

    class Meta:
        name = "audioChannelFormat"
        namespace = "urn:ebu:metadata-schema:ebucore"


